import{_ as a,o as t,c as o,a8 as r}from"./chunks/framework.R_sesYpn.js";const p=JSON.parse('{"title":"FAQ","description":"","frontmatter":{"title":"FAQ"},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/050_faq.md","lastUpdated":1786522245000}'),i={name:"guide/faq.md"};function n(s,e,l,u,c,h){return t(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h1> <p>Here are some questions that may or may not have been asked frequently. As a bonus, we&#39;ve even thrown in some answers.</p> <p>If your question is not here, or the answer didn&#39;t satisfy, please <a href="/guide/about.html#contact-us">contact us</a>. We&#39;re always happy to hear from you.</p> <h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2> <h3 id="corpus-compatibility" tabindex="-1">Corpus compatibility? <a class="header-anchor" href="#corpus-compatibility" aria-label="Permalink to &quot;Corpus compatibility?&quot;">​</a></h3> <p>For information about indexed corpus compatibility (&quot;does an older corpus work with a newer BlackLab, or do I have to reindex?&quot;, see the <a href="/development/downloads.html">downloads</a> page.</p> <h3 id="no-words-in-my-files" tabindex="-1">No words in my files? <a class="header-anchor" href="#no-words-in-my-files" aria-label="Permalink to &quot;No words in my files?&quot;">​</a></h3> <p>BlackLab needs <em>tokenized</em> input files. This means the word boundaries have already been determined so BlackLab can just index words as it parses the file.</p> <p>If your input files are not tokenized, BlackLab may complain that it didn&#39;t find any words. This can also happen if your input format configuration doesn&#39;t match your input data. See <a href="/guide/index-your-data/simple-example.html">how to configure indexing</a> or contact us.</p> <h3 id="why-is-blacklab-slow" tabindex="-1">Why is BlackLab slow? <a class="header-anchor" href="#why-is-blacklab-slow" aria-label="Permalink to &quot;Why is BlackLab slow?&quot;">​</a></h3> <p>This can have many causes:</p> <ul><li><p>Your <a href="/server/#memory-usage">memory configuration</a> may not be optimal.</p></li> <li><p>Your machine specifications may be insufficient for what you&#39;re trying to do. As a rough indication: we run a 4.5 billion token corpus on a (virtual) server with 50 GB of memory and 16 cores, with few simultaneous users that generally perform simple queries, with the occasional heavier query. This machine could probably handle heavier use than this.</p></li> <li><p>Certain types of BCQL queries can also be quite taxing on the machine. If you encounter an unexpectedly slow query, let us know and we&#39;ll see if we can help.</p></li></ul> <h3 id="view-whole-documents" tabindex="-1">View whole documents? <a class="header-anchor" href="#view-whole-documents" aria-label="Permalink to &quot;View whole documents?&quot;">​</a></h3> <p>You may be getting &quot;permission denied&quot; or such when trying to view a whole document in BlackLab Frontend or via BlackLab Server. This is due to the <code>corpusConfig.contentViewable</code> setting in the indexing configuration file.</p> <p>See the note about <code>contentViewable</code> on the <a href="/server/">BlackLab Server overview</a> page.</p> <h3 id="special-chars-in-urls" tabindex="-1">Special chars in URLs? <a class="header-anchor" href="#special-chars-in-urls" aria-label="Permalink to &quot;Special chars in URLs?&quot;">​</a></h3> <p>If you&#39;re not using Docker, you have to configure Tomcat to use Unicode URLs.</p> <p>To ensure the correct handling of accented characters in (search) URLs, you should <a href="https://tomcat.apache.org/tomcat-9.0-doc/config/http.html#Common_Attributes" target="_blank" rel="noreferrer">configure Tomcat</a> to interpret URLs as UTF-8 (by default, it does ISO-8859-1) by adding an attribute <code>URIEncoding=&quot;UTF-8&quot;</code> to the <code>&lt;Connector/&gt;</code> element with the attribute <code>port=&quot;8080&quot;</code> in Tomcat&#39;s <code>server.xml</code> file.</p> <p>Of course, make sure that URLs you send to BlackLab are URL-encoded using UTF-8 (so e.g. searching for <code>&quot;señor&quot;</code> corresponds to a request like <code>http://myserver/blacklab-server/mycorpus/hits?patt=%22se%C3%B1or%22</code>). <a href="https://blacklab-frontend.ivdnt.org/" target="_blank" rel="noreferrer">BlackLab Frontend</a> does this by default.</p> <h2 id="about-the-project" tabindex="-1">About the project <a class="header-anchor" href="#about-the-project" aria-label="Permalink to &quot;About the project&quot;">​</a></h2> <h3 id="who-is-blacklab-for" tabindex="-1">Who is BlackLab for? <a class="header-anchor" href="#who-is-blacklab-for" aria-label="Permalink to &quot;Who is BlackLab for?&quot;">​</a></h3> <p>BlackLab is a good choice if you want to search a large body of text annotated with extra information per word (e.g. lemma, part of speech, or any number of additional layers). It adds a number of search features to Lucene.</p> <p>With BlackLab, you can search for complex patterns of words (e.g. “find all nouns preceded by two or three adjectives”). It can accurately highlight matches (not just simple terms) in the original document or show them in a keyword-in-context (KWIC) view. It can quickly sort or group large result sets based on several criteria, including the exact words matched or words surrounding the match. It can also search inside specific XML tags, so you can search for people or places, for example.</p> <p>BlackLab supports <a href="/guide/index-your-data/create-an-index.html#supported-formats">a number of input formats</a> out of the box. Adding support for a new input format is a matter of writing a <a href="/guide/index-your-data/simple-example.html">configuration file</a>.</p> <h3 id="who-uses-blacklab" tabindex="-1">Who uses BlackLab? <a class="header-anchor" href="#who-uses-blacklab" aria-label="Permalink to &quot;Who uses BlackLab?&quot;">​</a></h3> <p><a href="./who-uses-blacklab.html">These fine projects and people!</a></p> <h3 id="blacklab-vs-others" tabindex="-1">BlackLab vs. others <a class="header-anchor" href="#blacklab-vs-others" aria-label="Permalink to &quot;BlackLab vs. others&quot;">​</a></h3> <p>Other corpus engines exist and have many great features. Each has their own strengths and weaknesses.</p> <p>What does BlackLab offer that others may not?</p> <ul><li>prioritizes good documentation and ease of use</li> <li>allows sorting and grouping hits on different properties, including context</li> <li>works with different input data formats</li> <li>supports (dependency) relations search, and you can combine this with token-based queries</li> <li>supports parallel corpora</li> <li>supports capturing parts of matches</li> <li>can be customized in many ways using various types of plugins (add your own query language, or add functions to BCQL, add a conversion step to indexing, etc.)</li> <li>provides a REST API so it&#39;s easy to use from any programming languages</li></ul> <h3 id="project-goals" tabindex="-1">Project goals? <a class="header-anchor" href="#project-goals" aria-label="Permalink to &quot;Project goals?&quot;">​</a></h3> <p>Roughly, these are our project goals, in no particular order:</p> <ul><li><strong>ease of use</strong> (continuously improve documentation, error messages, etc.)</li> <li><strong>ease of development and maintenance</strong> (continuously improve code quality)</li> <li><strong>versatility</strong> (add useful features)</li> <li><strong>scalability</strong> (make it possible and convenient to build and publish huge corpora)</li> <li><strong>inclusivity</strong> (be responsive, foster new users and contributors)</li></ul> <p>See this <a href="https://github.com/instituutnederlandsetaal/BlackLab/blob/dev/doc/bark/bark012-project-goals.md" target="_blank" rel="noreferrer">full article</a>.</p> <h3 id="do-you-use-ai" tabindex="-1">Do you use AI? <a class="header-anchor" href="#do-you-use-ai" aria-label="Permalink to &quot;Do you use AI?&quot;">​</a></h3> <p>The topic of AI / machine learning can be controversial. Let&#39;s clarify if and how we use it in BlackLab.</p> <h4 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h4> <p>Search in BlackLab does <em>not</em> use AI. Most of its users are in the scientific community, so reproducible results are important. A user specifies what they want to search for, and BlackLab finds it exactly as specified.</p> <h4 id="search-by-description" tabindex="-1">&quot;Search by description&quot; <a class="header-anchor" href="#search-by-description" aria-label="Permalink to &quot;&quot;Search by description&quot;&quot;">​</a></h4> <p>Because not everyone is familiar with the included query language (BCQL), we may develop an (optional) feature where you can input what you are looking for (&quot;find the most used adjectives that start with a b&quot;) which is then converted into a query for you. The user sees the query and can check if it looks correct. That feature would use generative AI (trained on example queries written by us), but it could be disabled if desired. It would likely not be a core part of BlackLab but a separate service that works with BlackLab Frontend.</p> <h4 id="tokenizing-and-tagging" tabindex="-1">Tokenizing and tagging <a class="header-anchor" href="#tokenizing-and-tagging" aria-label="Permalink to &quot;Tokenizing and tagging&quot;">​</a></h4> <p>Annotating input texts with linguistic information (&quot;tagging&quot;) is outside the scope of BlackLab itself. There are various tools available that can be combined with BlackLab for this purpose. Some of these tools use (a form of) pattern-recognizing AI.</p> <h4 id="development" tabindex="-1">Development <a class="header-anchor" href="#development" aria-label="Permalink to &quot;Development&quot;">​</a></h4> <p>Programmers working on BlackLab may use AI-based tools (such as GitHub Copilot, Claude Code or OpenAI Codex) to help them write code more efficiently, like most programmers nowadays. However, we believe that humans should always be fully in the loop and are committed to line-by-line reviewing anything written by an LLM.</p> <p>We recognize there are problems with AI, but also think that it can greatly benefit open-source projects like ours when used carefully.</p> <h3 id="is-blacklab-fast" tabindex="-1">Is BlackLab fast? <a class="header-anchor" href="#is-blacklab-fast" aria-label="Permalink to &quot;Is BlackLab fast?&quot;">​</a></h3> <p>We don&#39;t do regular search-offs, but in the past we&#39;ve determined that BlackLab offered similar speeds to other corpus search engines. Each engine tends to be better at some types of queries than others.</p> <p>We&#39;ve done a lot of work over the years to improve BlackLab&#39;s performance, and we invite you to see for yourself.</p> <h3 id="distributed-search" tabindex="-1">Distributed search? <a class="header-anchor" href="#distributed-search" aria-label="Permalink to &quot;Distributed search?&quot;">​</a></h3> <p>This is a feature we are looking in to, both to improve scalability and flexibility (maintaining a large corpus made up of various subcorpora).</p> <p>See our <a href="#future-plans">future plans</a>.</p> <h3 id="future-plans" tabindex="-1">Future plans <a class="header-anchor" href="#future-plans" aria-label="Permalink to &quot;Future plans&quot;">​</a></h3> <p>We will keep improving BlackLab as time goes on.</p> <p>Broadly speaking, these are our plans for the future:</p> <ul><li>Improve performance and memory requirements (ongoing)</li> <li>Keep up with new Lucene versions (ongoing)</li> <li>Scale to larger corpora by adding support for distributed search,
either through integration with Solr (experiment in progress) or via another route</li> <li>Keep up to date with new Java versions (ongoing)</li> <li>Make accessing and highlighting the original content of documents more flexible (stored in the index or accessed through an API)</li> <li>Enhance dependency relations search</li> <li>Integrate improvements and suggestions from the community (<a href="https://github.com/instituutnederlandsetaal/BlackLab/issues" target="_blank" rel="noreferrer">issues</a> and <a href="https://github.com/instituutnederlandsetaal/BlackLab/pulls" target="_blank" rel="noreferrer">pull requests</a> welcome!)</li></ul> <p>For more (somewhat technical) details, see the corresponding <a href="https://github.com/instituutnederlandsetaal/BlackLab/tree/dev/doc/bark#readme" target="_blank" rel="noreferrer">BARKs</a> (short descriptions of planned development and other information).</p>`,111)])])}const b=a(i,[["render",n]]);export{p as __pageData,b as default};
